import {position,legal,play,uci} from './rules.js';import {importPgn} from './importer.js';
const $=s=>document.querySelector(s),app=$('#app');let state={courses:JSON.parse(localStorage.getItem('anti-courses-v1')||'[]'),progress:JSON.parse(localStorage.getItem('anti-progress-v1')||'{}'),course:null,line:null,mode:'learn',step:0,selected:null,message:'',mistakes:0,complete:false,side:'w',preview:null};
const save=()=>{localStorage.setItem('anti-courses-v1',JSON.stringify(state.courses));localStorage.setItem('anti-progress-v1',JSON.stringify(state.progress))};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const stats=l=>state.progress[l.id]||{learned:false,attempts:0,success:0,mistakes:0};
function home(){state.course=null;app.innerHTML=`<div class="hero"><div><div class="eyebrow">Practice with purpose</div><h1>Know your next move.</h1><p class="subtitle">Build confidence in your antichess openings, one line at a time. Your studies and progress stay right here on your device.</p></div><div class="buttons"><button class="primary" id="import">＋ &nbsp;Import a study</button></div></div><div class="section-head"><h2>Your courses</h2><span class="course-meta">${state.courses.length} ${state.courses.length===1?'COURSE':'COURSES'}</span></div>${state.courses.length?state.courses.map((c,i)=>{let valid=c.lines.filter(l=>!l.error),learned=valid.filter(l=>stats(l).learned).length;return `<div class="panel card course-card"><div><div class="eyebrow">YOUR STUDY</div><h2>${esc(c.title)}</h2><p class="muted">${valid.length} drillable lines · ${learned} learned${c.lines.length-valid.length?` · ${c.lines.length-valid.length} need attention`:''}</p><div class="progress"><span style="width:${valid.length?learned/valid.length*100:0}%"></span></div></div><button data-open="${i}">Open course →</button></div>`}).join(''):`<div class="panel empty"><div><div class="eyebrow">A good place to start</div><h2>Your first line awaits.</h2><p class="subtitle">Export a Lichess antichess study as a PGN, then bring it here. Each chapter becomes a line you can practice.</p><div class="buttons"><button class="primary" id="empty-import">Import PGN</button><button id="demo">Try a sample</button></div></div><div class="empty-icon">♞</div></div>`}<p class="footer-note">Built for antichess. Captures are compulsory, and kings are ordinary pieces.</p>`;$('#import').onclick=importDialog;if($('#empty-import'))$('#empty-import').onclick=importDialog;if($('#demo'))$('#demo').onclick=()=>{state.preview=importPgn(DEMO);previewDialog()};document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>course(+b.dataset.open));}
function importDialog(){let el=document.createElement('div');el.className='modal';el.innerHTML=`<div class="panel"><div class="modal-head"><div><div class="eyebrow">Bring your own study</div><h2>Import a PGN</h2></div><button aria-label="Close">×</button></div><p class="muted">Export a study from Lichess, with comments and variations, then upload the file or paste its contents below. Chapters stay in their original order.</p><label class="file-label">Choose PGN file<input type="file" accept=".pgn,text/plain"></label><textarea placeholder="Paste your PGN here…"></textarea><label class="muted"><input type="checkbox"> Confirm missing variant tags mean antichess</label><div class="warning" hidden></div><div class="buttons" style="margin-top:18px"><button class="primary preview">Preview chapters →</button></div></div>`;document.body.append(el);el.querySelector('.modal-head button').onclick=()=>el.remove();el.querySelector('input[type=file]').onchange=async e=>{if(e.target.files[0])el.querySelector('textarea').value=await e.target.files[0].text()};el.querySelector('.preview').onclick=()=>{try{let text=el.querySelector('textarea').value;if(!text.trim())throw Error('Choose a PGN file or paste PGN text first.');state.preview=importPgn(text,el.querySelector('input[type=checkbox]').checked);el.remove();previewDialog()}catch(e){let w=el.querySelector('.warning');w.hidden=false;w.textContent=e.message}}}
function previewDialog(){let c=state.preview;let el=document.createElement('div');el.className='modal';el.innerHTML=`<div class="panel"><div class="modal-head"><div><div class="eyebrow">Import preview</div><h2>${esc(c.title)}</h2><p class="muted">${c.lines.length} chapters, in source order. Only validated main lines can be practiced.</p></div><button aria-label="Close">×</button></div>${c.lines.map((l,i)=>`<div class="line"><div class="line-number">${String(i+1).padStart(2,'0')}</div><div class="line-content"><div class="line-name">${esc(l.name)}</div><div class="line-detail ${l.error?'error':''}">${l.error?esc(l.error):`${l.steps.length} half-moves · ${l.tags.FEN?'custom starting position':'starting position'}`}</div></div><span class="badge">${l.error?'NOT TRAINABLE':'READY'}</span></div>`).join('')}<p class="muted">Variations remain in the source PGN; only the chapter’s main line is trained.</p><div class="buttons"><button class="primary save">Save course</button><button class="back">Back</button></div></div>`;document.body.append(el);el.querySelector('.modal-head button').onclick=()=>el.remove();el.querySelector('.back').onclick=()=>{el.remove();importDialog()};el.querySelector('.save').onclick=()=>{let idx=state.courses.findIndex(v=>v.id===c.id);if(idx>=0)state.courses[idx]=c;else state.courses.push(c);save();el.remove();home()}}
function course(index){state.course=index;let c=state.courses[index];app.innerHTML=`<button class="link" id="home">← All courses</button><div class="hero" style="margin-top:28px"><div><div class="eyebrow">Your course · ${c.lines.length} chapters</div><h1>${esc(c.title)}</h1><p class="subtitle">Work through your lines in the order they were authored. Practice and drill unlock as you learn.</p></div><div class="buttons"><button class="primary" id="next">Start learning →</button></div></div><div class="section-head"><h2>Course lines</h2><span class="course-meta">${c.lines.filter(l=>stats(l).learned).length} LEARNED</span></div><div class="panel">${c.lines.map((l,i)=>`<div class="line"><div class="line-number">${String(i+1).padStart(2,'0')}</div><div class="line-content"><div class="line-name">${esc(l.name)}</div><div class="line-detail ${l.error?'error':''}">${l.error?esc(l.error):`${l.steps.length} half-moves · ${stats(l).learned?'Learned':'Not learned yet'}`}</div></div>${l.error?'<span class="badge">DRAFT</span>':`<button data-line="${i}">Learn →</button>`}</div>`).join('')}</div>`;$('#home').onclick=home;$('#next').onclick=()=>{let i=c.lines.findIndex(l=>!l.error&&!stats(l).learned);if(i<0)i=c.lines.findIndex(l=>!l.error);if(i>=0)train(i,'learn')};document.querySelectorAll('[data-line]').forEach(b=>b.onclick=()=>train(+b.dataset.line,'learn'))}
const pieceNames={P:'pawn',N:'knight',B:'bishop',R:'rook',Q:'queen',K:'king'};
const pieceAsset=piece=>`./assets/cburnett/${piece===piece.toUpperCase()?'w':'b'}${piece.toUpperCase()}.svg`;
const pieceLabel=piece=>`${piece===piece.toUpperCase()?'white':'black'} ${pieceNames[piece.toUpperCase()]}`;
function train(i,mode){let c=state.courses[state.course],l=c.lines[i];state.line=i;state.mode=mode;state.step=0;state.selected=null;state.mistakes=0;state.message='';state.complete=false;state.side='w';state.pos=position(l.start);auto();renderTrain()}
function auto(){let l=state.courses[state.course].lines[state.line];while(state.step<l.steps.length&&state.pos.turn!==state.side){state.pos=position(l.steps[state.step].after);state.step++}if(state.step>=l.steps.length&&!state.complete){state.complete=true;let p=stats(l);p.attempts++;p.success++;p.mistakes+=state.mistakes;p.learned=true;p.last=Date.now();state.progress[l.id]=p;save()}}
function renderTrain(){let c=state.courses[state.course],l=c.lines[state.line],moves=legal(state.pos),sel=state.selected,targets=moves.filter(m=>m.from===sel);let next=l.steps[state.step];let feedback=state.message|| (state.complete?'Line complete. Nicely done.':state.mode==='learn'?'Find the next move in this line. Captures are compulsory.':'Recall the next move in this line.');let currentComment=state.step?l.steps.slice(Math.max(0,state.step-2),state.step).map(x=>x.comment).filter(Boolean).join(' '):l.intro;let learned=c.lines.filter(x=>!x.error&&stats(x).learned);app.innerHTML=`<button class="link" id="back">← Course lines</button><div style="margin:23px 0 20px"><div class="eyebrow">${esc(state.mode)} · LINE ${String(state.line+1).padStart(2,'0')} OF ${c.lines.length}</div><h2>${esc(l.name)}</h2><div class="muted">${esc(c.title)} &nbsp; / &nbsp; ${state.step} of ${l.steps.length} half-moves</div><div class="progress"><span style="width:${state.step/l.steps.length*100}%"></span></div></div><div class="training"><div class="board-wrap"><div class="board" role="grid" aria-label="Antichess board">${state.pos.board.map((row,y)=>row.map((piece,x)=>{let sq='abcdefgh'[x]+(8-y),target=targets.some(m=>m.to===sq);return `<button class="square ${(x+y)%2?'dark':'light'} ${sel===sq?'selected':''} ${target?'target':''} ${piece?'occupied':''}" data-square="${sq}" aria-label="${sq}${piece?' '+pieceLabel(piece):''}">${piece?`<img class="piece" src="${pieceAsset(piece)}" alt="" draggable="false">`:''}${x===0?`<span>${8-y}</span>`:''}</button>`}).join('')).join('')}</div><div class="mode"><button class="${state.mode==='learn'?'active':''}" data-mode="learn">Learn</button><button class="${state.mode==='practice'?'active':''}" data-mode="practice" ${!stats(l).learned?'disabled':''}>Practice</button><button class="${state.mode==='drill'?'active':''}" data-mode="drill" ${!stats(l).learned?'disabled':''}>Drill</button></div></div><div class="training-side"><div class="eyebrow">${state.complete?'Rehearsal finished':'Your turn · White'}</div><div class="status" aria-live="polite">${esc(feedback)}</div>${state.complete?`<div class="completion"><strong>Line learned</strong><p style="margin:7px 0 0">${state.mistakes?`${state.mistakes} ${state.mistakes===1?'mistake':'mistakes'} this attempt.`:'A clean run.'}</p></div>`:''}${currentComment&&state.mode==='learn'?`<div class="panel"><div class="eyebrow">Author's note</div><div class="muted">${esc(currentComment)}</div></div>`:''}<div class="buttons" style="margin-top:20px">${state.complete?'<button class="primary" id="nextline">Next line →</button>':`<button class="primary" id="hint">Hint</button>`}<button id="restart">Restart</button></div><p class="footer-note">You play White. The trainer follows the selected line for Black.</p><div class="eyebrow" style="margin-top:25px">Line so far</div><div class="moves">${l.steps.slice(0,state.step).map((s,i)=>`${s.side==='w'?Math.floor((Number(s.before.split(' ')[5])-1))+1+'. ':i===0?s.before.split(' ')[5]+'... ':''}${esc(s.san)}`).join(' ')||'Your first move is up.'}</div>${state.mode!=='learn'?`<p class="muted">${learned.length} learned ${learned.length===1?'line':'lines'} available for practice.</p>`:''}</div></div>`;$('#back').onclick=()=>course(state.course);$('#restart').onclick=()=>train(state.line,state.mode);let h=$('#hint');if(h)h.onclick=()=>{state.message=`Hint: move from ${next.uci.slice(0,2)} to ${next.uci.slice(2,4)}.`;renderTrain()};let n=$('#nextline');if(n)n.onclick=()=>{let ix;if(state.mode==='learn'){ix=c.lines.findIndex((x,j)=>j>state.line&&!x.error&&!stats(x).learned);if(ix<0)ix=c.lines.findIndex(x=>!x.error&&!stats(x).learned)}else{let options=c.lines.map((x,j)=>({x,j})).filter(o=>!o.x.error&&stats(o.x).learned&&o.j!==state.line).sort((a,b)=>stats(b.x).mistakes-stats(a.x).mistakes);ix=options[0]?.j??state.line}if(ix<0)course(state.course);else train(ix,state.mode)};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>train(state.line,b.dataset.mode));document.querySelectorAll('[data-square]').forEach(b=>b.onclick=()=>square(b.dataset.square));}
function square(s){if(state.complete)return;let moves=legal(state.pos),candidates=moves.filter(m=>m.from===state.selected&&m.to===s);if(candidates.length){let m=candidates[0];if(candidates.length>1){let choice=prompt('Promote to queen, rook, bishop, knight, or king? Enter Q, R, B, N, or K.','Q');if(!choice)return;m=candidates.find(x=>x.promotion===choice.toLowerCase());if(!m){state.message='Choose Q, R, B, N, or K.';renderTrain();return}}let l=state.courses[state.course].lines[state.line],expected=l.steps[state.step];if(uci(m)!==expected.uci){state.mistakes++;state.message='That move is legal, but it is not the move in this line. Try again.';state.selected=null;renderTrain();return}state.pos=play(state.pos,m);state.step++;state.selected=null;state.message='';auto();renderTrain();return}if(moves.some(m=>m.from===s)){state.selected=s;state.message=''}else if(state.selected)state.message='That move is not legal in this position. Captures are compulsory.';renderTrain()}
const DEMO=`[Event "Sample study: 01 - First steps"]\n[Variant "Antichess"]\n\n1. e3 {Open the diagonal for your bishop.} e6 2. d4 d5 *\n\n[Event "Sample study: 02 - A different setup"]\n[Variant "Antichess"]\n\n1. e3 e6 2. b3 b6 *`;
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});home();

// Pointer events let a piece be dragged by mouse, finger, or stylus without
// changing the existing tap-to-move and keyboard interactions.
let drag = null;
let suppressDragClick = false;
app.addEventListener('pointerdown', event => {
  const squareElement = event.target.closest('.square');
  if (!squareElement || state.complete || !event.isPrimary || (event.pointerType === 'mouse' && event.button !== 0)) return;
  const from = squareElement.dataset.square;
  if (!legal(state.pos).some(move => move.from === from)) return;
  const piece = squareElement.querySelector('.piece');
  if (!piece) return;
  drag = { pointerId: event.pointerId, from, startX: event.clientX, startY: event.clientY, square: squareElement, piece, ghost: null, moved: false };
  squareElement.setPointerCapture(event.pointerId);
});
app.addEventListener('pointermove', event => {
  if (!drag || event.pointerId !== drag.pointerId) return;
  if (!drag.moved && Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY) > 8) {
    drag.moved = true;
    drag.ghost = drag.piece.cloneNode();
    const size = drag.square.getBoundingClientRect().width * .88;
    Object.assign(drag.ghost.style, {position:'fixed', width:`${size}px`, height:`${size}px`, zIndex:'100', pointerEvents:'none', transform:'translate(-50%, -50%)'});
    drag.ghost.classList.add('drag-ghost');
    document.body.append(drag.ghost);
    drag.piece.classList.add('drag-origin');
  }
  if (drag.moved) {
    event.preventDefault();
    drag.ghost.style.left = `${event.clientX}px`;
    drag.ghost.style.top = `${event.clientY}px`;
  }
});
function endDrag(event, cancelled = false) {
  if (!drag || event.pointerId !== drag.pointerId) return;
  const current = drag;
  drag = null;
  current.ghost?.remove();
  current.piece.classList.remove('drag-origin');
  if (!current.moved) return;
  const destination = document.elementFromPoint(event.clientX, event.clientY)?.closest('.square');
  suppressDragClick = true;
  setTimeout(() => { suppressDragClick = false; }, 0);
  if (!cancelled && destination && destination.closest('.board') && destination.dataset.square !== current.from) {
    square(current.from);
    square(destination.dataset.square);
  }
}
app.addEventListener('pointerup', event => endDrag(event));
app.addEventListener('pointercancel', event => endDrag(event, true));
app.addEventListener('click', event => {
  if (suppressDragClick) { event.preventDefault(); event.stopImmediatePropagation(); }
}, true);
